$r05_body$;
  before_entry jsonb;
  after_entry jsonb;
  certified_before text;
BEGIN
  IF current_setting('uskoci.r05.disposable',true) IS DISTINCT FROM 'LOCAL_ONLY'
     OR current_user<>'postgres' OR current_database()<>'postgres'
     OR to_regrole('cli_login_postgres') IS NOT NULL THEN
    RAISE EXCEPTION 'R05_HOSTED_OR_NONDISPOSABLE_TARGET_REFUSED' USING errcode='55000';
  END IF;
  PERFORM set_config('search_path','pg_catalog',true);
  PERFORM set_config('lock_timeout','5s',true);
  PERFORM set_config('statement_timeout','45s',true);
  IF md5(target_body) IS DISTINCT FROM '1354cc27a2a58976dab28debfeeb241d'
     OR (SELECT md5(replace(prosrc,E'\r\n',E'\n'))
         FROM pg_proc WHERE oid=to_regprocedure(signature))
        IS DISTINCT FROM 'a845d98b624ae4ac8ec33159beb8bb17' THEN
    RAISE EXCEPTION 'R05_SOURCE_PREDECESSOR_OR_TARGET_CHANGED' USING errcode='55000';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang
    WHERE p.oid=to_regprocedure(signature)
      AND p.proowner='postgres'::regrole AND p.prosecdef AND p.provolatile='s'
      AND l.lanname='plpgsql' AND p.prorettype='integer'::regtype
      AND p.prokind='f' AND NOT p.proretset AND p.pronargs=2
      AND p.proconfig=ARRAY['search_path=pg_catalog']::text[]
      AND p.proacl::text='{postgres=X/postgres}'
  ) THEN RAISE EXCEPTION 'R05_TIME_TIER_AUTHORITY_DRIFT' USING errcode='55000'; END IF;
  IF (SELECT md5(prosrc) FROM pg_proc
      WHERE oid=to_regprocedure('private.worker_available_periods(uuid,timestamp with time zone,timestamp with time zone,text)'))
      IS DISTINCT FROM '5107af3020a3beb7bb45e6e90e7a203b'
     OR (SELECT md5(prosrc) FROM pg_proc
      WHERE oid=to_regprocedure('private.availability_is_future(text,timestamp with time zone,timestamp with time zone,timestamp with time zone)'))
      IS DISTINCT FROM '3a1aee763e9fe3d0f06d6ba04ef21aac' THEN
    RAISE EXCEPTION 'R05_CALENDAR_SOURCE_DRIFT' USING errcode='55000';
  END IF;
  -- The current closure/source certificate is NOT ready on DEV.
  -- Refuse a change rather than rebind or silently replace its digest.
  IF private.retention_ai_source_ready() IS DISTINCT FROM TRUE OR
     private.closure_source_digest_v5() IS DISTINCT FROM
       (SELECT sha256 FROM private.closure_source_v5 WHERE singleton) THEN
    RAISE EXCEPTION 'R05_CLOSURE_NOT_READY' USING errcode='55000';
  END IF;
  certified_before:=private.closure_source_digest_v5();
  SELECT to_jsonb(p) INTO before_entry FROM pg_proc p WHERE p.oid=to_regprocedure(signature);
  IF before_entry IS NULL THEN
    RAISE EXCEPTION 'R05_TIME_TIER_NOT_FOUND' USING errcode='55000';
  END IF;
  -- One replace-in-place: no tables, indexes, triggers, new grants or new RPCs.
  EXECUTE format($r05_create$
    CREATE OR REPLACE FUNCTION private.worker_need_time_tier_v1(nid uuid,pid uuid)
      RETURNS integer LANGUAGE plpgsql STABLE SECURITY DEFINER
      SET search_path TO 'pg_catalog' AS %L$r05_create$,target_body);
  SELECT to_jsonb(p) INTO after_entry FROM pg_proc p WHERE p.oid=to_regprocedure(signature);
  IF after_entry-'prosrc' IS DISTINCT FROM before_entry-'prosrc'
      OR after_entry->>'prosrc' IS DISTINCT FROM target_body THEN
    RAISE EXCEPTION 'R05_TIME_TIER_ATTRIBUTE_CHANGED' USING errcode='55000';
  END IF;
  IF private.retention_ai_source_ready() IS DISTINCT FROM TRUE
     OR private.closure_source_digest_v5() IS DISTINCT FROM certified_before THEN
    RAISE EXCEPTION 'R05_CLOSURE_MOVED' USING errcode='55000';
  END IF;
END;
